#include <stdio.h>
int main(){
    int a[6] = {23, 88, 5, 61, 40, 12};
    int i, j, key;
    for(i=1; i<6; i++){
        key = a[i];
        j = i-1;
        while(j>=0 && a[j] < key){
            a[j+1] = a[j];
            j--;
        }
        a[j+1] = key;
    }
    for(i=0; i<6; i++) printf("%d", a[i]);
    return 0;
}

#include <stdio.h>
#include <string.h>

int main() {
    char *p = "aaabbbccd";
    char result[100];
    int i = 0, j = 0, count;
    int len = strlen(p);
    while (i < len) {
        count = 1;
        while (i + count < len && p[i] == p[i + count]) {
            count++;
        }
        result[j++] = p[i];
        if (count > 1) {
            j += sprintf(result + j, "%d", count);
        }
        i += count;
    }
    result[j] = '\0';
    printf("%s", result);
    return 0;
}

#include <stdio.h>

typedef struct {
    int id;
    double width;
    double height;
} Rect;

void initRect(Rect *r, int id, double w, double h){
    r->id = id;
    r->width = w;
    r->height = h;
}

void scaleRect(Rect *r, double factor){
    r->width = r->width * factor;
    r->height = r->height * factor;
}

double area(Rect *r){
    return r->width * r->height;
}

int main(){
    Rect rect;
    initRect(&rect, 7001, 4.0, 5.0);
    scaleRect(&rect, 1.5);
    printf("%d and %.2f", rect.id, area(&rect));
    return 0;
}

enum Level { LOW, MEDIUM, HIGH }
public class Main {
    public static void main(String[] args) {
        Level lv = Level.valueOf("MEDIUM");
        int score = 0;
        switch (lv) {
            case LOW: score = 1; break;
            case MEDIUM: score = 2; break;
            case HIGH: score = 3; break;
        }
        System.out.print(lv.ordinal() + score);
    }
